      var tot = r.pick([20, 25, 40, 50]), pc = r.pick([40, 60, 80, 90]), salt = tot * pc / 100;
      return { q: ['You purify ' + tot + ' g of rock salt and get ' + salt + ' g of pure salt. What percentage of the rock salt was salt?', 'تنقّي ' + tot + ' g من الملح الصخري فتحصل على ' + salt + ' g من الملح النقي. ما النسبة المئوية للملح في الملح الصخري؟'], a: pc,
        s: [w(['Dissolve, filter off the sand, then evaporate', 'أذِب ثم رشّح الرمل ثم بخّر'], ['The sand is removed by', 'يُزال الرمل بـ'], ['filtering', 'الترشيح'], '', [['evaporating', 'التبخير', 'Evaporating leaves the salt.', 'التبخير يُبقي الملح.']]), ['Salt ÷ total', 'الملح ÷ الكلي', salt + ' ÷ ' + tot + ' =', pc / 100], ['As a percentage', 'كنسبة مئوية', (pc / 100) + ' × 100 =', pc]], miss: [[100 - pc, 'That is the sand and other impurities.', 'هذا الرمل والشوائب.']] };
