  var HALF = [['Pb²⁺ + ?e⁻ → Pb', 2], ['Al³⁺ + ?e⁻ → Al', 3], ['Na⁺ + ?e⁻ → Na', 1], ['2Br⁻ → Br₂ + ?e⁻', 2], ['2Cl⁻ → Cl₂ + ?e⁻', 2], ['2O²⁻ → O₂ + ?e⁻', 4], ['Cu²⁺ + ?e⁻ → Cu', 2]];
