    trap: function () { return { q: ['A student writes the half-equations for molten lead bromide. One line is wrong. Tap it.', 'طالب يكتب المعادلات النصفية لبروميد الرصاص المصهور. سطر واحد خاطئ. انقر عليه.'], w: 1, why: ['Pb²⁺ needs two electrons to become a lead atom: Pb²⁺ + 2e⁻ → Pb.', 'Pb²⁺ يحتاج إلكترونين ليصبح ذرة رصاص: Pb²⁺ + 2e⁻ → Pb.'], l: [['Lead ions go to the cathode', 'أيونات الرصاص تتجه إلى المهبط'], 'Pb²⁺ + e⁻ → Pb', '2Br⁻ → Br₂ + 2e⁻'] }; },
    explain: [['Why must an ionic compound be molten or dissolved to be electrolysed?', 'لماذا يجب أن يكون المركب الأيوني مصهورًا أو مذابًا ليُحلَّل كهربائيًا؟'], ['Only then are its ions free to move to the electrodes.', 'عندها فقط تكون أيوناته حرة الحركة نحو القطبين.'], ['Solids have no ions.', 'المواد الصلبة بلا أيونات.'], ['Heat makes the electricity stronger.', 'الحرارة تقوّي الكهرباء.']]
