    trap: function () { return { q: ['A diver goes from 10 m down to 20 m down in water. One line is wrong. Tap it.', 'غواص ينزل من عمق 10 m إلى 20 m في الماء. سطر واحد خاطئ. انقر عليه.'], w: 1, why: ['Pressure grows with depth: twice as deep gives twice the water pressure, not less.', 'الضغط يزداد مع العمق: ضعف العمق يعطي ضعف ضغط الماء لا أقل.'], l: ['10 × 1000 × 10 = 100000 Pa', ['At 20 m the water pressure is halved', 'عند 20 m يتنصف ضغط الماء'], '20 × 1000 × 10 = 200000 Pa'] }; },
    explain: [['Why is a dam much thicker at the bottom than at the top?', 'لماذا يكون السد أسمك كثيرًا في أسفله منه في أعلاه؟'], ['Water pressure grows with depth, so the bottom must withstand the greatest push.', 'ضغط الماء يزداد مع العمق، فيجب أن يتحمل الأسفل أشد دفع.'], ['The top holds less water so it needs less concrete for looks.', 'الأعلى يحمل ماءً أقل فيحتاج خرسانة أقل للمظهر.'], ['Water is heavier at the surface.', 'الماء أثقل عند السطح.']]
