    trap: function () { return { q: ['A student describes the blood. One line is wrong. Tap it.', 'طالب يصف الدم. سطر واحد خاطئ. انقر عليه.'], w: 1, why: ['White blood cells fight infection. Red blood cells carry oxygen.', 'خلايا الدم البيضاء تحارب العدوى، والحمراء تحمل الأكسجين.'], l: [['Plasma carries dissolved glucose', 'البلازما تحمل الغلوكوز المذاب'], ['White blood cells carry oxygen', 'خلايا الدم البيضاء تحمل الأكسجين'], ['Platelets help a cut clot', 'الصفائح تعين الجرح على التخثر']] }; },
