    trap: function () { return { q: ['A student explains how an apple forms. One line is wrong. Tap it.', 'طالب يشرح كيف تتكون التفاحة. سطر واحد خاطئ. انقر عليه.'], w: 1, why: ['The ovule becomes the seed. The ovary becomes the fruit.', 'البويضة تصبح البذرة، والمبيض يصبح الثمرة.'], l: [['Pollen lands on the stigma', 'تسقط حبوب اللقاح على الميسم'], ['The ovule becomes the fruit', 'البويضة تصبح الثمرة'], ['The pips inside are the seeds', 'البذور داخلها هي البذور الناتجة']] }; },
    explain: [['Why do farmers sometimes bring beehives into their orchards?', 'لماذا يجلب المزارعون أحيانًا خلايا النحل إلى بساتينهم؟'], ['Bees carry pollen between flowers, so more flowers are fertilised and more fruit forms.', 'النحل ينقل اللقاح بين الأزهار، فتُخصب أزهار أكثر وتتكون ثمار أكثر.'], ['Bees eat the pests.', 'النحل يأكل الآفات.'], ['Honey feeds the trees.', 'العسل يغذي الأشجار.']]
