      if (lv === 2) return ask(r.pick([[['At equilibrium, what is true?', 'عند الاتزان، ما الصحيح؟'], ['Forward and backward rates are equal', 'معدلا التفاعل الأمامي والعكسي متساويان'], ['The amounts of reactants and products are equal', 'كميات المتفاعلات والنواتج متساوية', 'The rates are equal. The amounts can be very different.', 'المعدلات متساوية، أما الكميات فقد تختلف كثيرًا.'], ['Both reactions have stopped', 'توقف التفاعلان', 'They carry on, at the same rate.', 'يستمران بالمعدل نفسه.'], ['Equal rates keep the amounts steady', 'تساوي المعدلات يثبّت الكميات']], [['Why can equilibrium only be reached in a closed system?', 'لماذا لا يُبلغ الاتزان إلا في نظام مغلق؟'], ['Nothing can escape, so products are there to react back', 'لا شيء يفلت، فتبقى النواتج لتتفاعل عكسيًا'], ['Open containers are too cold', 'الأوعية المفتوحة باردة جدًا', 'Temperature is not the issue.', 'الحرارة ليست المشكلة.'], ['Air stops the reaction', 'الهواء يوقف التفاعل', 'The issue is products escaping.', 'المشكلة فرار النواتج.'], ['Escaping gas cannot react back', 'الغاز الفار لا يتفاعل عكسيًا']]]));
      var t = r.pick([[['heating it', 'تسخينه'], ['white', 'أبيض'], ['blue', 'أزرق']], [['adding water', 'إضافة الماء'], ['blue', 'أزرق'], ['white', 'أبيض']]]);
