    trap: function () { return { q: ['A student describes a reaction at equilibrium. One line is wrong. Tap it.', 'طالب يصف تفاعلًا عند الاتزان. سطر واحد خاطئ. انقر عليه.'], w: 1, why: ['At equilibrium both reactions continue at the same rate. It is dynamic, not stopped.', 'عند الاتزان يستمر التفاعلان بالمعدل نفسه؛ فهو حركي لا متوقف.'], l: [['It is in a closed system', 'هو في نظام مغلق'], ['Both reactions have stopped', 'توقف التفاعلان'], ['The amounts of each substance stay the same', 'كمية كل مادة تبقى ثابتة']] }; },
    explain: [['Why is equilibrium called dynamic?', 'لماذا يوصف الاتزان بأنه حركي؟'], ['Both reactions keep going; they just balance each other, so nothing seems to change.', 'التفاعلان مستمران لكنهما متوازنان، فلا يبدو أن شيئًا يتغير.'], ['Because the amounts keep changing quickly.', 'لأن الكميات تتغير بسرعة.'], ['Because the container moves.', 'لأن الوعاء يتحرك.']]
